def bestand(apps, schema_editor):
    """Vorbelegung für Einheiten mit Musik; getippte Instrumente auf die Liste bringen."""
    from music.instrument_list import canonical, ensure_defaults, key

    Instrument = apps.get_model("music", "Instrument")
    Organization = apps.get_model("organizations", "Organization")
    models_ = {name: apps.get_model("music", name) for name in USERS}
    orgs = set()
